# Campfire book and ceremonies walkthrough on the demo troop at phone size.
#   python3 scripts/e2e-campfire.py <shots dir>
import os, sys
from playwright.sync_api import sync_playwright
BASE = 'http://localhost:5288'; SP = sys.argv[1]; os.makedirs(SP, exist_ok=True); errors = []
def shot(p, n, full=False): p.wait_for_timeout(450); p.screenshot(path=f'{SP}/{n}.png', full_page=full)
def page(b, code, w=390, h=844):
    ctx = b.new_context(viewport={'width': w, 'height': h}, device_scale_factor=2, is_mobile=True, has_touch=True)
    p = ctx.new_page(); p.on('pageerror', lambda e: errors.append(str(e))); p.on('dialog', lambda d: d.accept())
    p.on('console', lambda m: m.type == 'error' and 'status of 40' not in m.text and errors.append(m.text))
    p.goto(f'{BASE}/?x=1#/join/{code}'); p.wait_for_selector('.app-main', timeout=20000); p.wait_for_timeout(2000)
    if p.locator('button:has-text("Later")').count(): p.click('button:has-text("Later")')
    return p
def overflow(p): return p.evaluate('document.documentElement.scrollWidth > innerWidth + 1')
with sync_playwright() as pw:
    b = pw.chromium.launch()
    L = page(b, 'XXXX-XXXX')
    L.goto(BASE + '/#/'); L.wait_for_selector('.tiles'); print('home tiles:', L.locator('.tile[href="#/campfire"]').count(), L.locator('.tile[href="#/ceremonies"]').count())
    L.click('.tile[href="#/campfire"]'); L.wait_for_selector('.fire-hero'); shot(L, 'c01-hub', True)
    L.click('.fire-list a[href="#/campfire/song/purple-stew"]'); L.wait_for_selector('.words-missing'); shot(L, 'c02-purple-stew')
    L.click('.words-missing button'); L.fill('.sheet textarea', 'Our troop sings this one loud.\n\nSecond verse here.'); L.click('.sheet button:has-text("Add to the book")')
    L.wait_for_selector('.song-words.troop'); print('troop words saved:', 'Second verse' in L.inner_text('.song-words.troop'))
    L.goto(BASE + '/#/campfire/song/clementine'); L.wait_for_selector('.song-words'); L.click('button:has-text("Fire light")'); L.click('button:has-text("Bigger text")'); shot(L, 'c03-clementine-night', True)
    L.click('button:has-text("Fire light")'); L.click('button:has-text("Bigger text")')
    L.click('button:has-text("Make favorite")'); L.wait_for_selector('button:has-text("★ Favorite")')
    L.goto(BASE + '/#/campfire?tab=skits'); L.wait_for_selector('.fire-rules'); shot(L, 'c04-skits')
    L.click('a[href="#/campfire/skit/invisible-bench"]'); L.wait_for_selector('.script'); shot(L, 'c05-skit', True)
    L.goto(BASE + '/#/campfire?tab=cheers'); L.wait_for_selector('.fire-list'); print('cheers:', L.locator('.fire-list li').count())
    L.goto(BASE + '/#/campfire?tab=plans'); L.click('a:has-text("Plan a campfire")'); L.wait_for_selector('.lu-add')
    L.fill('input[placeholder="Saturday night campfire"]', 'Fall Camporee campfire')
    L.click('button:has-text("Fill it for me")'); L.wait_for_selector('.lu-who'); n = L.locator('.lu-row').count(); print('filled acts:', n)
    L.locator('.lu-who').nth(0).fill('Eagles'); L.locator('.lu-who').nth(3).fill('Foxes')
    L.locator('.lu-btns button[aria-label="Move down"]').nth(0).click()
    L.fill('input[aria-label="Add something else"]', 'Welcome and awards'); L.click('.lu-add form button')
    L.click('button:has-text("From the book")'); L.click('.sheet .chip:has-text("Run-ons")'); L.locator('.pick-list button:not([disabled])').first.click(); L.keyboard.press('Escape')
    shot(L, 'c06-plan-editor', True)
    L.click('button:has-text("Save campfire")'); L.wait_for_selector('a:has-text("Emcee mode")'); shot(L, 'c07-plan', True)
    print('saved acts:', L.locator('.lineup li').count(), '(expected', n + 2, ')')
    L.click('a:has-text("Emcee mode")'); L.wait_for_selector('.emcee'); shot(L, 'c08-emcee-1')
    for _ in range(3): L.click('.em-foot button:has-text("Next")')
    shot(L, 'c09-emcee-4')
    L.click('.em-top button'); L.wait_for_selector('a:has-text("Emcee mode")')
    L.goto(BASE + '/#/campfire'); L.wait_for_selector('.fire-hero'); print('hero shows next campfire:', 'Emcee mode' in L.inner_text('.fire-hero'))
    L.fill('input[aria-label="Search the campfire book"]', 'moose'); L.wait_for_timeout(300); print('search moose:', L.locator('.fire-list li').count())
    # Kim's Game
    L.goto(BASE + '/#/campfire/kim'); L.click('.kim-level >> nth=0'); L.wait_for_selector('.kim-grid'); shot(L, 'c10-kim-look')
    shown = L.locator('.kim-cell').all_inner_texts()
    L.click('button:has-text("I\'m ready")'); L.wait_for_selector('.kim-grid.pick')
    for t in shown[:6]: L.locator(f'.kim-grid.pick button:text-is("{t}")').click()
    L.locator('.kim-grid.pick button:not(.on)').first.click(); shot(L, 'c11-kim-pick')
    L.click('button:has-text("Check my answers")'); L.wait_for_selector('.kim-result'); print('kim score:', L.inner_text('.kim-score').replace('\n', '')); shot(L, 'c12-kim-result', True)
    # ceremonies
    L.goto(BASE + '/#/more'); L.click('a[href="#/ceremonies"]'); L.wait_for_selector('.cer-quick'); shot(L, 'c13-ceremonies', True)
    L.click('a[href="#/ceremonies/open-indoor"]'); L.wait_for_selector('.cer-steps'); shot(L, 'c14-open-indoor', True)
    L.click('a:has-text("Lead it")'); L.wait_for_selector('.emcee.lead'); shot(L, 'c15-lead-1')
    for _ in range(3): L.click('.em-foot button:has-text("Next")')
    print('pledge shown in lead mode:', L.locator('.em-words.pledge').count()); shot(L, 'c16-lead-pledge')
    L.click('.em-body'); L.wait_for_timeout(200); print('tap advances to step:', L.inner_text('.em-count'))
    L.click('.em-top button[aria-label="Stop leading"]'); L.wait_for_selector('.cer-steps')
    L.goto(BASE + '/#/ceremonies/fold'); L.wait_for_selector('.fold-diagram'); shot(L, 'c17-fold', True)
    L.goto(BASE + '/#/ceremonies/retire'); L.wait_for_selector('.cer-steps'); shot(L, 'c18-retire', True)
    L.goto(BASE + '/#/ceremonies/flag-etiquette'); L.wait_for_selector('.facts'); shot(L, 'c19-etiquette', True)
    L.goto(BASE + '/#/ceremonies'); L.click('.head-btn'); L.fill('.sheet input', 'Webelos crossover'); L.fill('.sheet textarea', 'SPL: Will the new scouts please come forward.\n* The Webelos cross the bridge.\nScoutmaster: Welcome to Troop 23!')
    L.click('.sheet button:has-text("Add to the book")'); L.wait_for_timeout(800); L.click('a:has-text("Webelos crossover")'); L.wait_for_selector('.cer-steps'); print('troop ceremony steps:', L.locator('.cer-step').count())
    L.click('button:has-text("Delete")'); L.wait_for_selector('.cer-quick')
    # demo scout (a patrol leader) and small phones
    s = page(b, 'XXXX-XXXS', 320, 640)
    for path, sel, name in [('campfire', '.fire-hero', 'c20-hub-320'), ('campfire/song/railroad', '.song-words', 'c21-song-320'), ('ceremonies/morning-colors', '.cer-steps', 'c22-cer-320'), ('campfire/kim', '.kim-levels', 'c23-kim-320')]:
        s.goto(f'{BASE}/#/{path}'); s.wait_for_selector(sel); shot(s, name); print(name, 'overflow:', overflow(s))
    plan = L.evaluate("location.hash")
    s.goto(BASE + '/#/campfire?tab=plans'); s.wait_for_selector('.fire-list'); s.click('.fire-list a >> nth=0'); s.click('a:has-text("Emcee mode")'); s.wait_for_selector('.emcee'); shot(s, 'c24-emcee-320'); print('emcee 320 overflow:', overflow(s))
    s.goto(BASE + '/#/ceremonies/retire/lead'); s.wait_for_selector('.emcee'); s.click('.em-foot button:has-text("Next")'); shot(s, 'c25-lead-320')
    # clean up the test plan and words
    L.goto(BASE + '/#/campfire?tab=plans'); L.wait_for_selector('.fire-list'); L.click('.fire-list a >> nth=0'); L.wait_for_selector('.lineup'); L.click('button:has-text("Delete plan")'); L.wait_for_selector('.fire-tabs')
    L.goto(BASE + '/#/campfire/song/purple-stew'); L.wait_for_selector('.song-words.troop'); L.click('button:has-text("Remove our words")'); L.wait_for_selector('.words-missing')
    L.goto(BASE + '/#/campfire/song/clementine'); L.wait_for_selector('button:has-text("★ Favorite")'); L.click('button:has-text("★ Favorite")')
    b.close()
print('ERRORS', errors)
